def game(A, B):
    if A < 1 or B < 1:
        return "Non-drinkers can't play"
    mikes_turns = range(1, 2 * (A // 2 + 1), 2)
    joes_turns = range(2, 2 * (B // 2 + 1), 2)
    if sum(mikes_turns) <= A and sum(joes_turns) > B:
        return "Mike"
    if sum(joes_turns) <= B and sum(mikes_turns) > A:
        return "Joe"
    return "Joe" if sum(joes_turns) <= B else "Mike"
